"""Small baseline JPEGs for the first wallpaper frame (never generated by QML)."""
import hashlib
import os
from pathlib import Path

from PyQt6.QtCore import QIODevice, QSaveFile, QSize
from PyQt6.QtGui import QImageReader

ROOT = Path(__file__).resolve().parent
INCLUDED = ROOT / "included"
BUNDLED = ROOT / "previews"
CACHE = Path(os.environ.get("XDG_CACHE_HOME", Path.home() / ".cache")) / "pond-interface/wallpaper-previews"
WIDTH = 960


def generate(source, destination):
    reader = QImageReader(str(source))
    reader.setAutoTransform(True)
    size = reader.size()
    if size.width() > WIDTH:
        reader.setScaledSize(QSize(WIDTH, max(1, round(size.height() * WIDTH / size.width()))))
    image = reader.read()
    if image.isNull():
        raise ValueError(f"Could not read wallpaper: {reader.errorString()}")
    destination.parent.mkdir(parents=True, exist_ok=True)
    output = QSaveFile(str(destination))
    if not output.open(QIODevice.OpenModeFlag.WriteOnly):
        raise OSError(output.errorString())
    if not image.save(output, "JPG", 82) or not output.commit():
        raise OSError(f"Could not save wallpaper preview: {output.errorString()}")
    return destination


def preview(path):
    source = Path(path).expanduser().resolve(strict=True)
    bundled = BUNDLED / source.name
    if source.parent == INCLUDED and bundled.is_file():
        return bundled
    stat = source.stat()
    key = hashlib.sha256(f"{source}:{stat.st_mtime_ns}:{stat.st_size}".encode()).hexdigest()
    destination = CACHE / f"{key}.jpg"
    return destination if destination.is_file() else generate(source, destination)


if __name__ == "__main__":
    import json
    for entry in json.loads((ROOT / "catalog.json").read_text()):
        generate(INCLUDED / entry["file"], BUNDLED / entry["file"])
